INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-samples-001', 'Make five sample products before asking for orders', 'pre_launch', 'first_priority', '{"title":"Make five sample products before asking for orders","what_it_means":"People should see real examples before they trust a new business.","what_to_do":["Create five sample products in different styles.","Record close-up videos while making them.","Use the samples in your first Instagram posts and WhatsApp status."],"example":"{{businessName}} can make five sample {{product}} for birthdays, farewell gifts, best friends, couples, and college events in {{location}}.","why_this_helps":"People understand what you sell faster when they see real products instead of plain posters.","how_to_check":"Check if people reply asking for price, preview, or delivery after seeing the samples."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp","reels"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["launch_awareness","first_10_customers","build_trust"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["no_content","trust_issue","unclear_order_process"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-top-actions-002', 'Start with three actions, not a huge plan', 'pre_launch', 'simple_summary', '{"title":"Start with three actions, not a huge plan","what_it_means":"A new business needs a few clear first moves, not too many tasks.","what_to_do":["Prepare sample products.","Write the WhatsApp order steps.","Post a simple launch teaser."],"example":"{{businessName}} can say: We are opening soon in {{location}}. Send your idea on WhatsApp, see a preview, and confirm before we make it.","why_this_helps":"Simple first actions help you move today instead of waiting for a perfect launch.","how_to_check":"Check if at least five people ask what you are launching or how to order."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["first_10_customers","launch_awareness"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["no_content","unclear_order_process"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-seven-day-003', 'Use a seven-day launch countdown', 'launch_week', 'seven_day_plan', '{"title":"Use a seven-day launch countdown","what_it_means":"People remember a launch better when they see it many times in different ways.","what_to_do":["Post one simple launch update every day for seven days.","Show samples, price range, order steps, delivery area, and launch offer.","Repeat the same update on WhatsApp status."],"example":"{{businessName}} can run a seven-day countdown for {{audience}} in {{location}} with one product video each day.","why_this_helps":"A countdown gives people time to notice, ask questions, and share it with friends.","how_to_check":"Check story views, replies, saves, and WhatsApp messages during the seven days."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp","stories","reels"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["launch_awareness","first_30_customers"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["not_enough_awareness","no_content"]', 'easy', 'important', 'first_7_days', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-preorder-004', 'Collect interested people before opening', 'first_customers', 'first_priority', '{"title":"Collect interested people before opening","what_it_means":"You do not need full orders before launch. You need a list of people who want to see the first products.","what_to_do":["Ask people to message the word preview.","Save their names in a simple list.","Send them first access when samples are ready."],"example":"{{businessName}} can post: Message preview if you want to see the first custom gift samples before launch.","why_this_helps":"A small list gives you warm people to contact on launch day.","how_to_check":"Check how many people message preview and what product they ask about."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["first_10_customers","first_30_customers"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["not_enough_awareness","trust_issue"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-google-005', 'Set up Google Business before launch day', 'google_business', 'google_business_action', '{"title":"Set up Google Business before launch day","what_it_means":"Local buyers trust a business more when they can find it on Google.","what_to_do":["Add business name, category, location, hours, and contact method.","Upload sample product photos.","Add a post saying launch orders are opening soon."],"example":"{{businessName}} can add photos of sample {{product}} and mention delivery or pickup in {{deliveryArea}}.","why_this_helps":"People in {{location}} can check if the business looks real before messaging.","how_to_check":"Check profile views, direction clicks, calls, and WhatsApp clicks."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["google_business"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["launch_awareness","build_trust"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["no_google_presence","trust_issue"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
