  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-pre-launch-offer-006', 'Use a simple launch offer', 'offers', 'offer_idea', '{"title":"Use a simple launch offer","what_it_means":"A launch offer should be easy to understand and easy to explain.","what_to_do":["Give the first few buyers a small gift-packing add-on.","Avoid confusing discounts.","Make the offer clear in one line."],"example":"{{businessName}} can say: First 20 launch orders get free gift packing in {{location}}.","why_this_helps":"A clear offer gives people a reason to order early without making the brand look cheap.","how_to_check":"Check how many people mention the launch offer while messaging."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["first_10_customers","more_orders"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["price_confusion","not_enough_awareness"]', 'easy', 'important', 'launch_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-custom-preview-001', 'Send a design preview before making the product', 'customised_products', 'confidence_step', '{"title":"Send a design preview before making the product","what_it_means":"Customers should see the look before you start making the order.","what_to_do":["Ask for name, photo, colour, size, and spelling.","Send a simple preview image or mockup.","Start making only after the customer confirms."],"example":"{{businessName}} can reply: I will send a preview first. Please check name, photo, colour, size, and spelling before I make it.","why_this_helps":"This prevents mistakes and makes customers feel safe before paying.","how_to_check":"Check if fewer people ask what happens if the design is wrong."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp","instagram"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["trust_issue","quality_doubt","unclear_order_process"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-custom-safe-order-002', 'Use a safe six-step custom order process', 'customised_products', 'first_priority', '{"title":"Use a safe six-step custom order process","what_it_means":"Custom orders need a clear process because small mistakes can create big problems.","what_to_do":["Customer sends name, photo, design idea, and delivery date.","Shop sends preview.","Customer confirms details.","Customer pays advance.","Product is made.","Final photo is sent before delivery."],"example":"{{businessName}} can pin this process in Instagram highlights and send it as the first WhatsApp reply.","why_this_helps":"Customers trust the order more when every step is clear.","how_to_check":"Check if customers send complete details faster after reading the process."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp","instagram"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["sell_custom_products","build_trust"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["unclear_order_process","delivery_doubt","trust_issue"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
