  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-custom-advance-payment-003', 'Explain advance payment in a calm way', 'customised_products', 'customer_question', '{"title":"Explain advance payment in a calm way","what_it_means":"Customers should understand why advance payment is needed for custom work.","what_to_do":["Ask for advance only after preview and timing are confirmed.","Explain that custom material and making time are reserved.","Send a simple payment confirmation message."],"example":"{{businessName}} can say: Once you confirm the preview, we take advance so we can reserve material and start your custom order.","why_this_helps":"Clear payment rules reduce doubt and awkward price conversations.","how_to_check":"Check if fewer customers stop replying when advance payment is mentioned."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["price_confusion","trust_issue"]', 'easy', 'important', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
