  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-custom-final-photo-004', 'Send a final photo before delivery', 'customised_products', 'confidence_step', '{"title":"Send a final photo before delivery","what_it_means":"Customers feel safer when they see the finished product before it reaches them.","what_to_do":["Take one clear final photo.","Send it before delivery or pickup.","Ask the customer to confirm the details once more."],"example":"{{businessName}} can send: Your order is ready. Please check the final photo before delivery in {{deliveryArea}}.","why_this_helps":"It reduces delivery-time worry and shows that the shop checks details.","how_to_check":"Check if customers reply faster and share happier feedback after delivery."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["delivery_doubt","quality_doubt"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
