  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-custom-material-005', 'Show the material before people ask', 'customised_products', 'confidence_step', '{"title":"Show the material before people ask","what_it_means":"People want to know if the product will look and feel good in real life.","what_to_do":["Record close-up videos of the material.","Show thickness, finish, size, and packaging.","Mention care instructions if needed."],"example":"{{businessName}} can post a Reel showing the material of a custom gift before the design is added.","why_this_helps":"Material clarity reduces quality doubt and makes price easier to accept.","how_to_check":"Check if people ask fewer basic quality questions in messages."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp","reels"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","explain_product"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["quality_doubt","trust_issue"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
  product_type_tags, business_model_tags, goal_tags, budget_tags,
  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-whatsapp-first-reply-001', 'Use a first reply that collects the right details', 'whatsapp', 'whatsapp_message', '{"title":"Use a first reply that collects the right details","what_it_means":"The first reply should make ordering easy without a long conversation.","what_to_do":["Ask for product type, name/photo/design, date needed, and delivery area.","Keep the reply friendly and short.","Save it as a WhatsApp quick reply."],"example":"Hi, thanks for messaging {{businessName}}. Please send the product idea, name/photo/design, date needed, and area in {{location}}. I will reply with price and preview steps.","why_this_helps":"You get useful details early, and customers feel guided.","how_to_check":"Check if more customers send complete order details in the first message."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["first_10_customers","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["unclear_order_process"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
INSERT OR REPLACE INTO strategy_blocks (
  id, title, domain, section_type, content_json,
  category_tags, launch_status_tags, audience_tags, platform_tags,
