  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-whatsapp-price-reply-002', 'Give price without sounding unsure', 'whatsapp', 'whatsapp_message', '{"title":"Give price without sounding unsure","what_it_means":"Customers should know what affects the price.","what_to_do":["Share a starting price or price range.","Mention what can change the price.","Confirm final price after preview details."],"example":"{{businessName}} can say: Prices start from {{priceRange}}. Final price depends on product size, design detail, and delivery area.","why_this_helps":"Price clarity brings serious buyers and reduces back-and-forth.","how_to_check":"Check if more people continue the chat after receiving price."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["sell_custom_products","build_trust"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["price_confusion"]', 'easy', 'important', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
