  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-whatsapp-preview-confirm-003', 'Ask for preview confirmation in one clean message', 'whatsapp', 'whatsapp_message', '{"title":"Ask for preview confirmation in one clean message","what_it_means":"The customer must confirm small details before the order starts.","what_to_do":["Send the preview.","Ask them to check spelling, photo, colour, size, and date.","Start only after they reply confirmed."],"example":"{{businessName}} can send: Please check the preview carefully. Confirm name spelling, photo, colour, size, and delivery date in {{location}}. I will start making it after you reply confirmed.","why_this_helps":"It protects both the customer and the shop from avoidable mistakes.","how_to_check":"Check if confirmed previews reduce correction requests later."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["quality_doubt","unclear_order_process"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
