) VALUES ('sl-instagram-bio-001', 'Write an Instagram bio that explains ordering', 'instagram', 'instagram_action', '{"title":"Write an Instagram bio that explains ordering","what_it_means":"A new visitor should understand what you sell and how to order in five seconds.","what_to_do":["Say what you sell.","Mention preview before making.","Mention WhatsApp ordering and local delivery."],"example":"Customised gifts in {{location}}. Send your idea on WhatsApp. Preview before making. Delivery and pickup available.","why_this_helps":"A clear bio turns profile visits into messages.","how_to_check":"Check if profile visitors start messaging instead of only viewing posts."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["launch_awareness","first_10_customers","explain_product"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["unclear_order_process","no_content"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
