) VALUES ('sl-instagram-highlights-002', 'Create four Instagram highlights before launch', 'instagram', 'instagram_action', '{"title":"Create four Instagram highlights before launch","what_it_means":"Highlights help new visitors find basic answers without asking.","what_to_do":["Create highlights named Samples, How to Order, Price, and Delivery.","Add one simple story to each highlight.","Update them as questions come in."],"example":"{{businessName}} can keep How to Order as four story slides: send idea, get preview, confirm, receive in {{location}}.","why_this_helps":"People trust businesses that answer basic questions clearly.","how_to_check":"Check if fewer people ask the same basic questions in DMs."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","stories"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","explain_product"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["unclear_order_process","trust_issue"]', 'easy', 'important', 'next_2_days', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
