  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-instagram-reel-making-003', 'Record making videos, not only final photos', 'instagram', 'instagram_action', '{"title":"Record making videos, not only final photos","what_it_means":"People trust custom products more when they see the work happening.","what_to_do":["Record the product before customisation.","Record the making step.","Show the final packed product."],"example":"{{businessName}} can post a Reel showing a name/photo idea becoming a finished gift for a student in {{location}}.","why_this_helps":"Making videos prove that the product is real and handmade with care.","how_to_check":"Check watch time, saves, shares, and messages after each Reel."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","reels"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["trust_issue","quality_doubt","no_content"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
