) VALUES ('sl-local-college-001', 'Start with college gift moments', 'local_marketing', 'local_action', '{"title":"Start with college gift moments","what_it_means":"Students buy gifts for birthdays, farewells, friends, couples, and small celebrations.","what_to_do":["Create posts for each college gift moment.","Ask friends to share in student groups.","Offer pickup or local delivery near college areas."],"example":"{{businessName}} can post: Farewell gift for your best friend in {{location}}? Send the name/photo and we will show a preview.","why_this_helps":"Specific student moments are easier to remember than a general gift post.","how_to_check":"Check which occasion gets the most replies and saves."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp","local_groups"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["first_30_customers","launch_awareness"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["not_enough_awareness"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
