  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('sl-question-design-wrong-001', 'Answer what happens if the design is wrong', 'trust_building', 'customer_question', '{"title":"Answer what happens if the design is wrong","what_it_means":"Custom product buyers need to know how mistakes are handled.","what_to_do":["Explain the preview confirmation process.","Explain what the shop will fix if the mistake is from the shop side.","Keep the wording calm and clear."],"example":"{{businessName}} can say: We make only after preview confirmation. If our side makes a mistake after that, we will fix it clearly.","why_this_helps":"A clear mistake policy makes customers less afraid to order.","how_to_check":"Check if people ask fewer fear-based questions before paying."}', '["retail","customised_products","gifts"]', '["pre_launch"]', '["students","gen_z"]', '["instagram","whatsapp"]', '["customised_product"]', '["online_order","delivery","pickup","local_store"]', '["build_trust","sell_custom_products"]', '["no_budget","low_budget"]', '["india","kerala","kozhikode","calicut","local_city","college_area"]', '["quality_doubt","trust_issue"]', 'easy', 'important', 'this_week', 5, 'beginner', 1, 'review-001', 'review-001', 'manual-test');
